{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, approx_quantile(c.duration/1e6,0.5) caller_p50_ms, approx_quantile(s.duration/1e6,0.5) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-basic-service' AND s.service_name='ts-train-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "Basic's outgoing POST to train byNames takes about 4.66 s at the caller, while train's server span takes about 3.5 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_span_kind, span_name, attr_http_request_method m, count(*) n, approx_quantile(duration/1e6,0.5) p50_ms, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND attr_span_kind='Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "Basic's client POST spans have a median of 9 ms but a p95 of about 4.66 s; the GET client spans stay fast."
        }
